void process_lru_command(conn *c, token_t *tokens, size_t ntokens) {
    if (ntokens < 2)
        return;

    if (strncmp(tokens[1].value, "tune", tokens[1].length) == 0) {
        if (ntokens != 5)
            return;

        uint32_t hot_pct = 0, warm_pct = 0, hot_age = 0, warm_age = 0;
        if (string_to_uint32(tokens[2].value, tokens[2].length, &hot_pct) != 0 ||
            string_to_uint32(tokens[3].value, tokens[3].length, &warm_pct) != 0 ||
            string_to_uint32(tokens[4].value, tokens[4].length, &hot_age) != 0 ||
            string_to_uint32(tokens[5].value, tokens[5].length, &warm_age) != 0) {
            conn_send_error(c, "Invalid numeric argument in tune command.");
            return;
        }

        if (hot_pct <= warm_pct) {
            conn_send_error(c, "Hot percentage must be greater than warm percentage.");
            return;
        }

        if (hot_age < warm_age) {
            conn_send_error(c, "Hot age must be greater than warm age.");
            return;
        }

        c->lru_hot_pct = hot_pct;
        c->lru_warm_pct = warm_pct;
        c->lru_hot_age = hot_age;
        c->lru_warm_age = warm_age;
        conn_send(c, "LRU tune settings updated.");
    } else if (strncmp(tokens[1].value, "mode", tokens[1].length) == 0) {
        if (ntokens != 3)
            return;

        if (strncmp(tokens[2].value, "flat", tokens[2].length) == 0) {
            c->lru_mode = LRU_MODE_FLAT;
            conn_send(c, "LRU mode set to flat.");
        } else if (strncmp(tokens[2].value, "segmented", tokens[2].length) == 0) {
            c->lru_mode = LRU_MODE_SEGMENTED;
            conn_send(c, "LRU mode set to segmented.");
        } else {
            conn_send_error(c, "Invalid mode argument.");
        }
    } else if (strncmp(tokens[1].value, "temp_ttl", tokens[1].length) == 0) {
        if (ntokens != 3)
            return;

        uint32_t ttl = 0;
        if (string_to_uint32(tokens[2].value, tokens[2].length, &ttl) != 0) {
            conn_send_error(c, "Invalid TTL value.");
            return;
        }

        if (ttl > 0) {
            c->temp_ttl = ttl;
            conn_send(c, "Temporary TTL set.");
        } else {
            c->temp_ttl = 0;
            conn_send(c, "Temporary TTL cleared.");
        }
    } else {
        conn_send_error(c, "Unknown LRU command.");
    }
}

void process_lru_command(conn *c, token_t *tokens, size_t ntokens) {
    if (ntokens < 2) {
        conn_send(c, "ERROR: Insufficient arguments for LRU command.\r\n", strlen("ERROR: Insufficient arguments for LRU command.\r\n"));
        return;
    }

    if (strcmp(tokens[0].value, "tune") == 0) {
        if (ntokens != 5) {
            conn_send(c, "ERROR: Invalid number of arguments for 'tune' command.\r\n", strlen("ERROR: Invalid number of arguments for 'tune' command.\r\n"));
            return;
        }

        int hot_pct, warm_pct;
        double age_factor;

        if (sscanf(tokens[1].value, "%d", &hot_pct) != 1 || hot_pct < 0 || hot_pct > 100) {
            conn_send(c, "ERROR: Invalid hot percentage value.\r\n", strlen("ERROR: Invalid hot percentage value.\r\n"));
            return;
        }

        if (sscanf(tokens[2].value, "%d", &warm_pct) != 1 || warm_pct < 0 || warm_pct > 100) {
            conn_send(c, "ERROR: Invalid warm percentage value.\r\n", strlen("ERROR: Invalid warm percentage value.\r\n"));
            return;
        }

        if (sscanf(tokens[3].value, "%lf", &age_factor) != 1 || age_factor <= 0) {
            conn_send(c, "ERROR: Invalid age factor value.\r\n", strlen("ERROR: Invalid age factor value.\r\n"));
            return;
        }

        // Assume these functions exist and update the LRU settings
        lru_tune(hot_pct, warm_pct, age_factor);
        conn_send(c, "SUCCESS: LRU tuning updated.\r\n", strlen("SUCCESS: LRU tuning updated.\r\n"));
    }
    else if (strcmp(tokens[0].value, "mode") == 0) {
        if (ntokens != 2) {
            conn_send(c, "ERROR: Invalid number of arguments for 'mode' command.\r\n", strlen("ERROR: Invalid number of arguments for 'mode' command.\r\n"));
            return;
        }

        if (strcmp(tokens[1].value, "flat") == 0) {
            lru_set_mode(LRU_MODE_FLAT);
            conn_send(c, "SUCCESS: LRU mode set to flat.\r\n", strlen("SUCCESS: LRU mode set to flat.\r\n"));
        }
        else if (strcmp(tokens[1].value, "segmented") == 0) {
            lru_set_mode(LRU_MODE_SEGMENTED);
            conn_send(c, "SUCCESS: LRU mode set to segmented.\r\n", strlen("SUCCESS: LRU mode set to segmented.\r\n"));
        }
        else {
            conn_send(c, "ERROR: Invalid LRU mode. Expected 'flat' or 'segmented'.\r\n", strlen("ERROR: Invalid LRU mode. Expected 'flat' or 'segmented'.\r\n"));
        }
    }
    else if (strcmp(tokens[0].value, "temp_ttl") == 0) {
        if (ntokens != 2) {
            conn_send(c, "ERROR: Invalid number of arguments for 'temp_ttl' command.\r\n", strlen("ERROR: Invalid number of arguments for 'temp_ttl' command.\r\n"));
            return;
        }

        int ttl;
        if (sscanf(tokens[1].value, "%d", &ttl) != 1 || ttl < 0) {
            conn_send(c, "ERROR: Invalid TTL value.\r\n", strlen("ERROR: Invalid TTL value.\r\n"));
            return;
        }

        lru_set_temp_ttl(ttl);
        conn_send(c, "SUCCESS: Temporary TTL set.\r\n", strlen("SUCCESS: Temporary TTL set.\r\n"));
    }
    else {
        conn_send(c, "ERROR: Unknown LRU command.\r\n", strlen("ERROR: Unknown LRU command.\r\n"));
    }
}

